umask 027
printf '%s\n' "$pw" | htpasswd -i -c -B /etc/nginx/.staff_htpasswd reader >/dev/null
chown root:nginx /etc/nginx/.staff_htpasswd
chmod 640 /etc/nginx/.staff_htpasswd
